def transform(grid):
    """Restore cells marked 3 using the cell opposite them under 180-degree rotation."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = grid[h - 1 - r][w - 1 - c]
    return out
